329	/* Tries certain combinations of blocks in the level recursively. */
330	static unsigned
331	nextstep (pacmangamestruct *pp, 
332	          lev_t * level, const unsigned x, const unsigned y,
333	          unsigned dirvec[], unsigned ndirs)
334	{
335	    unsigned dirpos, curdir, inc = 0;
336	    int ret = 0;
337	
338	    while (ndirs > 0) {
339	        ndirs--;
340	        if (ndirs == 0) {
341	            curdir = dirvec[0];
342	        }
343	        else {
344	            dirpos = NRAND (ndirs);
345	            curdir = dirvec[dirpos];
346	            /* nope, no bufoverflow, but ndirs - 1 + 1 */
347	            dirvec[dirpos] = dirvec[ndirs];
348	            dirvec[ndirs] = curdir;
349	        }
350	
351	        switch (curdir) {
352	        case GO_UP:
353	            if (y < 1 || (ret = creatlevelblock (pp, level, x, y - 1))
354	                == 0)
355	                return 0;
356	            break;
357	        case GO_RIGHT:
358	            if (x > LEVWIDTH - 2 || (ret = creatlevelblock (pp, level, x + 1, y))
359	                == 0)
360	                return 0;
361	            break;
362	        case GO_DOWN:
363	            if (y > LEVHEIGHT - 2 || (ret = creatlevelblock (pp, level, x, y + 1))
364	                == 0)
365	                return 0;
366	            break;
367	        case GO_LEFT:
368	            if (x < 1 || (ret = creatlevelblock (pp, level, x - 1, y))
369	                == 0)
370	                return 0;
371	        }
372	        if (ret != -1)
373	            inc += (unsigned) ret;
374	    }
375	    if (inc == 0)
376	        inc = 1;
377	    return inc;
378	}
