380	static int
381	creatlevelblock (pacmangamestruct *pp, 
382	                 lev_t * level, const unsigned x, const unsigned y)
383	{
384	    unsigned tried = GETNB (TILES_COUNT);
385	    unsigned tilenr;
386	    unsigned ret;
387	    lev_t savedlev;
388	
389	    if (!pp->tiles) {
390	        pp->tiles = (struct tiles *) malloc (sizeof (def_tiles));
391	        memcpy (pp->tiles, def_tiles, sizeof (def_tiles));
392	    }
393	
394	    if (!((x < LEVWIDTH) && (y < LEVHEIGHT)))
395	        return 0;
396	
397	    if (checkunsetdef (level, x, y) != 0)
398	        return -1;
399	
400	    if (x == 0)
401	        tried &= ~(1 << 0);
402	    else if (x == 1)
403	        tried &= ~(1 << 4 | 1 << 5 | 1 << 6 | 1 << 8 | 1 << 9 | 1 << 10);
404	    else if (x == LEVWIDTH - 1)
405	        tried &= ~(1 << 0);
406	    else if (x == LEVWIDTH - 2)
407	        tried &= ~(1 << 2 | 1 << 3 | 1 << 6 | 1 << 7 | 1 << 8 | 1 << 10);
408	
409	    if (y == 1)
410	        tried &= ~(1 << 2 | 1 << 5 | 1 << 6 | 1 << 7 | 1 << 9 | 1 << 10);
411	    else if (y == 0)
412	        tried &= ~(1 << 1);
413	    else if (y == LEVHEIGHT - 1)
414	        tried &= ~(1 << 1);
415	    else if (y == LEVHEIGHT - 2)
416	        tried &= ~(1 << 3 | 1 << 4 | 1 << 7 | 1 << 8 | 1 << 9 | 1 << 10);
417	
418	    /* make a copy of the current level, so we can go back on the stack */
419	    (void) memcpy (&savedlev, level, sizeof (lev_t));
420	
421	    /* while there are still some blocks left to try */
422	    while (tried != 0x00) {
423	        tilenr = tileprob[NRAND (MAXTILEPROB)];
424	
425	        if (!TESTNB (tried, tilenr))
426	            continue;
427	
428	        if (tryset (level, x, y, pp->tiles[tilenr].block) != 0) {
429	            if ((ret = nextstep (pp, level, x, y, pp->tiles[tilenr].dirvec,
430	                                 pp->tiles[tilenr].ndirs)) != 0) {
431	                return ret + 1;
432	            }
433	            (void) memcpy (level, &savedlev, sizeof (lev_t));
434	        }
435	        tried &= ~(pp->tiles[tilenr].simular_to);
436	    }
437	    return 0;
438	}
