583	   and such.  Stupid algorithm, could be done better! */
584	static void
585	frmtlevel (pacmangamestruct *pp, lev_t * level)
586	{
587	    lev_t frmtlev;
588	    int x, y;
589	    int idx;
590	    register unsigned poscond;
591	    register unsigned poscond2;
592	
593	    clearlevel (&frmtlev);
594	    init_bonus_dots (pp, level);
595	    for (y = 0; y < LEVHEIGHT; y++)
596	        for (x = 0; x < LEVWIDTH; x++) {
597	
598	            if (checkset (level, x, y) == 0) {
599	                if (pacman_is_bonus_dot (pp, x, y, &idx)) {
600	                    frmtlev[y][x] = BLOCK_DOT_BONUS;
601	                }
602	                else {
603	                    frmtlev[y][x] = BLOCK_DOT_2;
604	                }
605	                continue;
606	            }
607	
608	            if ((*level)[y][x] == BLOCK_GHOST_ONLY) {
609	                frmtlev[y][x] = BLOCK_GHOST_ONLY;
610	                continue;
611	            }
612	
613	            poscond =
614	                (checksetout (level, x - 1, y - 1) != 0 ?
615	                 0x01U : 0U) |
616	                (checksetout (level, x + 1, y - 1) != 0 ?
617	                 0x02U : 0U) |
618	                (checksetout (level, x + 1, y + 1) != 0 ?
619	                 0x04U : 0U) |
620	                (checksetout (level, x - 1, y + 1) != 0 ? 0x08U : 0U);
621	
622	            poscond2 =
623	                (checksetout (level, x - 1, y) != 0 ?
624	                 0x01U : 0) |
625	                (checksetout (level, x, y - 1) != 0 ?
626	                 0x02U : 0) |
627	                (checksetout (level, x + 1, y) != 0 ?
628	                 0x04U : 0) |
629	                (checksetout (level, x, y + 1) != 0 ? 0x08U : 0);
630	
631	            switch (poscond) {
632	                /* completely filled */
633	            case 0x01U | 0x02U | 0x04U | 0x08U:
634	                frmtlev[y][x] = BLOCK_EMPTY;
635	                continue;
636	
637	                /* left to top corner */
638	            case 0x01U:
639	                frmtlev[y][x] = BLOCK_WALL_TL;
640	                continue;
641	                /* top to right corner */
642	            case 0x02U:
643	                frmtlev[y][x] = BLOCK_WALL_TR;
644	                continue;
645	                /* right to bottom corner */
646	            case 0x04U:
647	                frmtlev[y][x] = BLOCK_WALL_BR;
648	                continue;
649	                /* bottom to left corner */
650	            case 0x08U:
651	                frmtlev[y][x] = BLOCK_WALL_BL;

650	            case 0x08U:
651	                frmtlev[y][x] = BLOCK_WALL_BL;
652	                continue;
653	            }
654	
655	            switch (poscond2) {
656	            case 0x01U | 0x04U:
657	            case 0x01U | 0x04U | 0x08U:
658	            case 0x01U | 0x04U | 0x02U:
659	                frmtlev[y][x] = BLOCK_WALL_HO;
660	                continue;
661	            case 0x02U | 0x08U:
662	            case 0x02U | 0x08U | 0x01U:
663	            case 0x02U | 0x08U | 0x04U:
664	                frmtlev[y][x] = BLOCK_WALL_VE;
665	                continue;
666	            case 0x01U | 0x02U:
667	                frmtlev[y][x] = BLOCK_WALL_TL;
668	                continue;
669	            case 0x02U | 0x04U:
670	                frmtlev[y][x] = BLOCK_WALL_TR;
671	                continue;
672	            case 0x04U | 0x08U:
673	                frmtlev[y][x] = BLOCK_WALL_BR;
674	                continue;
675	            case 0x08U | 0x01U:
676	                frmtlev[y][x] = BLOCK_WALL_BL;
677	                continue;
678	            }
679	            switch (poscond) {
680	            case 0x02U | 0x04U | 0x08U:
681	                frmtlev[y][x] = BLOCK_WALL_TL;
682	                continue;
683	            case 0x01U | 0x04U | 0x08U:
684	                frmtlev[y][x] = BLOCK_WALL_TR;
685	                continue;
